Program CekHurufVokal
{ Menentukan apakah sebuah karakter huruf kecil merupakan huruf vokal tanpa struktur percabangan }

{ Deklarasi / Kamus }
KAMUS
    c : karakter
    isVokal : boolean

{ Deskripsi / Algoritma }
ALGORITMA:
    { Membaca masukan karakter huruf kecil }
    input(c)

    { Mengevaluasi ekspresi Boolean langsung ke dalam variabel isVokal }
    isVokal <- ((c = 'a') or (c = 'e') or (c = 'i') or (c = 'o') or (c = 'u'))

    { Menampilkan hasil Boolean }
    output(isVokal)
EndProgram

Algoritma Hitung_Keliling_Lingkaran
{ Menghitung keliling lingkaran berdasarkan masukan jari-jari dari pengguna }

Deklarasi:
  KONSTANTA pi = 3.14
  r : real        { jari-jari lingkaran }
  keliling : real { hasil keliling lingkaran }

Deskripsi:
  { Membaca masukan jari-jari dari pengguna }
  read(r)

  { Menghitung keliling lingkaran }
  keliling <- 2 * pi * r

  { Menampilkan hasil keluaran }
  write(keliling)

program KonversiSuhu
{ Mengonversi suhu dari satuan Celsius ke Fahrenheit }

KAMUS:
