Program KalkulatorPecahan
{ Menghitung a/b dan c/d: penjumlahan, pengurangan, perkalian, pembagian }

KAMUS
    a, b, c, d : integer     { masukan }
    x, y       : integer     { pembilang dan penyebut hasil }

ALGORITMA
    input(a, b, c, d)

    { Penjumlahan: a/b + c/d = (a*d + c*b) / (b*d) }
    x ← a * d + c * b
    y ← b * d
    output("Penjumlahan ", x, "/", y)

    { Pengurangan: a/b - c/d = (a*d - c*b) / (b*d) }
    x ← a * d - c * b
    y ← b * d
    output("Pengurangan ", x, "/", y)

    { Perkalian: a/b * c/d = (a*c) / (b*d) }
    x ← a * c
    y ← b * d
    output("Perkalian ", x, "/", y)

    { Pembagian: a/b : c/d = (a*d) / (b*c) }
    x ← a * d
    y ← b * c
    output("Pembagian ", x, "/", y)

