Algoritma BalikBilanganTigaDigit

{ Membalik urutan digit dari sebuah bilangan bulat positif tiga digit.
  Contoh: 123 menjadi 321 }

KAMUS
    n         : integer    { bilangan masukan, tiga digit }
    satuan    : integer    { digit satuan }
    puluhan   : integer    { digit puluhan }
    ratusan   : integer    { digit ratusan }
    hasil     : integer    { bilangan hasil pembalikan }

ALGORITMA
    input(n)

    satuan  <- n mod 10
    puluhan <- (n div 10) mod 10
    ratusan <- n div 100

    hasil <- satuan * 100 + puluhan * 10 + ratusan

    output(hasil)

