program nilai_mutlak
kamus
    x, mask, hasil : integer
algoritma
    input(x)

    // 1. Membuat bitmask (topeng bit)
    // Geser bit paling kiri (sign bit) ke kanan sebanyak 31 kali.
    // Jika x positif, mask = 0. Jika x negatif, mask = -1.
    mask <- x >> 31

    // 2. Menghitung nilai mutlak dengan rumus bitwise
    // Rumus: (x XOR mask) - mask
    hasil <- (x xor mask) - mask

    output(hasil)
endprogram

program nilaimutlak
kamus
    n, p, hasil : integer
algoritma
    input(n)

    // Trik pembagian matematika ideal:
    // Jika n bernilai positif/nol, p akan menghasilkan nilai 1
    // Jika n bernilai negatif, p akan menghasilakan nilai 0
    p <- (n + 2147483647 div 2147483647)

    // Mengubah p menjadi pengali tanda (+1 atau -1)
    hasil <- n * (2 * p - 1)

    output(hasil)
endprogram

