program KonversiKoin
{program untuk mengkonversi koin drachma menjadi attic talent, mine, dan oboli}
kamus
    total_drachma : INTEGER
    attic_talent  : INTEGER
    mine          : INTEGER
    oboli         : INTEGER
    sisa_drachma  : INTEGER
algoritma
    total_drachma = 100 {nilai untuk contoh}

    {Menghitung jumlah attic talent (1 talent = 6000 drachma)}
    attic_talent = total_drachma // 6000

    {Menyimpan sisa drachma setelah ditukar menjadi talent}
    sisa_drachma = total_drachma % 6000

    {Menghitung jumlah mine dari sisa drachma (1 mine = 100 drachma)}
    mine = sisa_drachma // 100

    {Menyimpan sisa drachma setelah ditukar menjadi mine}
    sisa_drachma = sisa_drachma % 100

    {Mengubah seluruh sisa drachma terakhir menjadi oboli (1 drachma = 6 oboli)}
    oboli = sisa_drachma * 6

    {Menampilkan keluaran secara berurutan}
    write attic_talent
    write mine
    write oboli
endprogram

program <digitMenaik>

kamus
     n : integer {variabel input bilangan}
     d1, d2 ,d3 ,d4 : integer {variabel untuk 4 digit}

algoritma
     read n {membaca satu bilangan bulat 4 digit}

     d1 <- n div 1000 { digit ribuan, misal 2345 div 1000 = 2 }
     d2 <- n div 100 mod 10 { digit ratusan, 2345 div 100 = 23 mod 10 = 3 }
     d3 <- n div 10 mod 10 { digit puluhan, 2345 div 10 = 234 mod 10 = 4 }
     d4 <- n mod 10 { digit satuan, 2345 mod 10 = 5 }

     write((d1 < d2) and (d2 < d3) and (d3 < d4)) { true jika menaik }

endprogram

