program Ceknegatif
kamus
    N     : integer    { Bilangan bulat masukan 32-bit }
    hasil : integer    { Output: 1 jika negatif, 0 jika bukan }

algoritma
    read(N)

    { Membagi N dengan batas atas maksimum integer 32-bit. }
    { N >= 0  =>  N div 2147483647 = 0   => -0  = 0 }
    { N < 0   =>  N div 2147483647 = -1  => -(-1) = 1 }
    hasil <- -1 * (N div 2147483647)

    write(hasil)

endprogram

program Ceknegatif
