program tukarkoin
kamus
    drachma, sisa_drachma : integer
    talenta_loteng, tambang, oboli : integer
algoritma
    read(drachma)

    { Konversi ke talenta loteng }
    { 1 talenta loteng = 60 tambang = 60 * 100 drachma = 6000 drachma }
    talenta_loteng <- drachma div 6000
    sisa_drachma <- drachma mod 6000

    { Konversi sisa drachma ke tambang }
    { 1 tambang = 100 drachma }
    tambang <- sisa_drachma div 100
    sisa_drachma <- sisa_drachma mod 100

    { Konversi sisa drachma ke oboli }
    { 1 drachma = 6 oboli }
    oboli <- sisa_drachma * 6

    output(talenta_loteng, tambang, oboli)
endprogram

