Algoritma Kalkulator_Pecahan

DEKLARASI:
    a, b, c, d : integer { Input pembilang dan penyebut }
    x, y       : integer { Variabel untuk menyimpan hasil pembilang dan penyebut }

ALGORITMA:
    // 1. Membaca masukan dari pengguna
    baca(a, b, c, d)

    // 2. Operasi Penjumlahan (a/b + c/d)
    x = (a * d) + (b * c)
    y = b * d
    tulis("Penjumlahan: ", x, "/", y)

    // 3. Operasi Pengurangan (a/b - c/d)
    x = (a * d) - (b * c)
    y = b * d
    tulis("Pengurangan: ", x, "/", y)

    // 4. Operasi Perkalian (a/b * c/d)
    x = a * c
    y = b * d
    tulis("Perkalian: ", x, "/", y)

    // 5. Operasi Pembagian (a/b : c/d = a/b * d/c)
    x = a * d
    y = b * c
    tulis("Pembagian: ", x, "/", y)

program kalkulator
kamus
    //a, b, c, d int
    //x_tambah, y_tambah int
    //x_kurang, y_kurang int
    //x_kali, y_kali int
    //x_bagi, y_bagi int
aloritma
    input(a, b, c, d)
    //penjumlahan
    x_tambah = (a*b)+(b*c)
    y_tambah = b*d
    output("penjumlahan", x_tambah, "/", y_tambah)

    //pengurangan
    x_kurang = (a*d)-(b*c)
    y_kurang = b*d
    output("pengurangan", x_kurang, "/", y_kurang)

    //perkalian
    x_kali = a*c
    y_kali = b*d
    output("perkalian", x_kali, "/", y_kali)

    //pembagian
    x_bagi = a*d
    y_bagi = b*c
    output("pembagian", x_bagi, "/", y_bagi)

