    { 1. Membaca nilai Boolean dari masukan }
    read(input_nilai)

    { 2. Membalikkan nilai Boolean menggunakan operator logika NOT }
    hasil <- NOT input_nilai

    { 3. Menampilkan hasil kebalikan ke layar }
    write(hasil)

