program CekDigitMenaik
kamus
    n, a, b, c, d : integer
    menaik        : boolean
algoritma
    input(n)
    a <- n div 1000          { digit ribuan }
    b <- (n div 100) mod 10  { digit ratusan }
    c <- (n div 10) mod 10   { digit puluhan }
    d <- n mod 10            { digit satuan }
    menaik <- (a < b) and (b < c) and (c < d)
    output(menaik)

program cek_vokal;

