Program NilaiMutlak

Kamus:
    x : bilangan bulat
    tanda : bilangan bulat

Algoritma:
    input(x)

    { Jika x positif, (x + 2147483648) div 2147483648 akan menghasilkan 1 }
    { Jika x negatif, (x + 2147483648) div 2147483648 akan menghasilkan 0 }
    tanda <- (x + 2147483648) div 2147483648

    { Jika tanda = 1, maka x * (2*1 - 1) = x * 1 = x }
    { Jika tanda = 0, maka x * (2*0 - 1) = x * -1 = -x }
    output(x * (2 * tanda - 1))

endprogram

