    // Mengekstraksi digit dari kiri ke kanan:
    // - Ribuan  : n / 1000
    // - Ratusan : (n / 100) % 10
    // - Puluhan : (n / 10) % 10
    // - Satuan  : n % 10
    // Menggunakan tanda kurung untuk menyusun ekspresi Boolean secara tepat.
    cout << boolalpha << (
        ((n / 1000) < ((n / 100) % 10)) &&
        (((n / 100) % 10) < ((n / 10) % 10)) &&
        (((n / 10) % 10) < (n % 10))
    ) << endl;

    return 0;
}

