#include <iostream>

using namespace std;

int main() {
    long long total_drachma;

    // Membaca masukan jumlah drachma
    cin >> total_drachma;

    // Konversi satuan:
    // 1 attic talent = 60 mine = 60 * 100 drachma = 6.000 drachma
    // 1 mine = 100 drachma
    // 1 oboli = 1/6 drachma -> berarti oboli dihitung dari sisa drachma setelah dikonversi ke mine, lalu dikali 6.

    long long attic_talent = total_drachma / 6000;
    long long sisa_drachma_setelah_talent = total_drachma % 6000;

    long long mine = sisa_drachma_setelah_talent / 100;
    long long sisa_drachma_setelah_mine = sisa_drachma_setelah_mine = sisa_drachma_setelah_talent % 100; // sisa drachma yang kurang dari 1 mine

    long long oboli = sisa_drachma_setelah_mine * 6;

    // Menampilkan keluaran tiga bilangan bulat: attic talent, mine, dan oboli
    cout << attic_talent << " " << mine << " " << oboli << endl;

    return 0;
}

