#include <iostream>

using namespace std;

int main() {
    long long health, score, level;

    // Membaca masukan: health, score, dan level
    cin >> health >> score >> level;

    // Syarat permainan dapat dilanjutkan (can_continue):
    // health > 0 DAN (
    //     (level == 1 DAN score >= 1000) ATAU
    //     (level == 2 DAN score >= 3000) ATAU
    //     (score >= 7000)
    // )
    bool can_continue = (health > 0) && (
        ((level == 1) && (score >= 1000)) ||
        ((level == 2) && (score >= 3000)) ||
        (score >= 7000)
    );

    // Keluaran bernilai true jika game over (artinya TIDAK bisa melanjutkan / !can_continue)
    // dan false jika pemain masih dapat melanjutkan permainan.
    cout << boolalpha << !can_continue << endl;

    return 0;
}

