algorithm HitungLuasLingkaran
{
    Deklarasi konstanta pi = 3.14
    Deklarasi variabel r, luas bertipe real
}
{
    // Membaca input jari-jari lingkaran
    read(r)

    // Menghitung luas menggunakan rumus pi * r^2
    luas <- pi * r * r

    // Menampilkan hasil luas lingkaran
    write(luas)
}

algorithm HitungLuasPermukaanBola
{
    Deklarasi konstanta pi = 3.14
    Deklarasi variabel r, luasPermukaan bertipe real
}
{
    // Membaca input jari-jari bola
    read(r)

    // Menghitung luas permukaan menggunakan rumus 4 * pi * r^2
    luasPermukaan <- 4 * pi * r * r

    // Menampilkan hasil luas permukaan bola
    write(luasPermukaan)
}

algorithm HitungVolumeBola
{
    Deklarasi konstanta pi = 3.14
    Deklarasi variabel r, volume bertipe real
}
{
    // Membaca input jari-jari bola
    read(r)

    // Menghitung volume menggunakan rumus (4/3) * pi * r^3
    volume <- (4.0 / 3.0) * pi * r * r * r

    // Menampilkan hasil volume bola
    write(volume)
}

algorithm HitungVolumeKerucut
{
    Deklarasi konstanta pi = 3.14
    Deklarasi variabel r, t bertipe integer
    Deklarasi variabel volume bertipe real
}
{
    // Membaca input jari-jari alas dan tinggi kerucut
    read(r, t)

    // Menghitung volume menggunakan rumus (1/3) * pi * r^2 * t
    volume <- (1.0 / 3.0) * pi * r * r * t

    // Menampilkan hasil volume kerucut
    write(volume)
}

