function computeF(x) {
    const numerator = Math.pow(x, 3) + (3 * x);
    const denominator = Math.pow(x, 4) - (3 * Math.pow(x, 2)) + 4;
    return numerator / denominator;
}

// Menguji dengan nilai input dari contoh
const inputs = [1.6, -1.4];

inputs.forEach(x => {
    const result = computeF(x);
    // Memformat hasil ke 7 angka di belakang koma agar sesuai dengan contoh
    console.log(`Input: \({x} -> Result:\){result.toFixed(7)}`);
});

