program NilaiMutlak
{Program untuk menghitung nilai mutlak suatu bilangan bulat signed 32-bit tanpa struktur percabangan}

kamus
    N : integer { Input bilangan bulat }
    faktor_pengali : integer { Variabel untuk menentukan arah tanda (+1, -1, atau 0) }
    hasil : integer { Output nilai mutlak }

algoritma
    input(N)

    { Jika N positif, (N > 0) bernilai 1 dan (N < 0) bernilai 0, maka pengali = 1 }
    { Jika N negatif, (N > 0) bernilai 0 and (N < 0) bernilai 1, maka pengali = -1 }
    faktor_pengali <- (N > 0) - (N < 0)

    { Mengalikan angka asli dengan faktor pengalinya untuk membuang tanda negatif }
    hasil <- N * faktor_pengali

    output(hasil)

endprogram

program NilaiMutlak
{ Menghitung nilai mutlak bilangan bulat 32-bit tanpa percabangan }

kamus

    x     : integer    { bilangan masukan, 32 bit }
    mask  : integer    { penanda tanda bilangan: 0 jika x >= 0, -1 jika x < 0 }
    hasil : integer    { nilai mutlak dari x }

algoritma

    input(x)
    mask  ← x >> 31
    hasil ← (x + mask) XOR mask
    output(hasil)

endprogram

ALGORITMA Nilai_Mutlak_Tanpa_Kondisional

DEKLARASI:
    x      : integer  { bilangan bulat 32-bit }
    mask   : integer  { bit tanda }
    mutlak : integer  { hasil nilai mutlak }

DESKRIPSI:
    BACA x

    { Membuat mask: menghasilkan 0 jika positif, -1 jika negatif }
    mask ← x >> 31

    { Menghitung nilai mutlak dengan operasi bitwise XOR dan pengurangan }
    mutlak ← (x XOR mask) - mask

    TULIS mutlak

ALGORITMA Periksa_Negatif_32Bit

DEKLARASI:
    bilangan : integer  { Bilangan bulat 32-bit yang diperiksa }
    hasil    : integer  { Output berupa 1 atau 0 }

DESKRIPSI:
    BACA bilangan

    { Geser bit ke kanan secara logis sebanyak 31 bit untuk mengambil bit tanda }
    hasil ← bilangan >>> 31

    TULIS hasil

ALGORITMA Sisip_Angka_Tengah

DEKLARASI:
    bilangan   : integer  { bilangan 4 digit }
    sisipan    : integer  { angka 1 digit yang disisipkan }
    depan      : integer  { menampung 2 digit depan }
    belakang   : integer  { menampung 2 digit belakang }
    hasil_baru : integer  { hasil akhir setelah penyisipan }

DESKRIPSI:
    BACA bilangan, sisipan

    { Memecah bilangan menjadi dua bagian }
    depan    ← bilangan DIV 100
    belakang ← bilangan MOD 100

    { Menyisipkan angka baru dan menggabungkannya kembali }
    hasil_baru ← (depan * 1000) + (sisipan * 100) + belakang

    TULIS hasil_baru

