package main

import "fmt"

func isMultiple(a int, b int) bool {
    return a%b == 0
}

func main() {
    // Pengujian sesuai dengan contoh data uji
    fmt.Println(isMultiple(5, 10))  // false
    fmt.Println(isMultiple(10, 5))  // true
    fmt.Println(isMultiple(4, 4))   // true
    fmt.Println(isMultiple(3, 6))   // false[cite: 3]
    fmt.Println(isMultiple(7, 14))  // false[cite: 3]
    fmt.Println(isMultiple(14, 7))  // true[cite: 3]
}

package main

import "fmt"

func isValidScore(score int) bool {
    // Memeriksa apakah score >= 0 DAN score <= 100 secara bersamaan
    return (0 <= score) && (score <= 100)
}

func main() {
    // Contoh pengujian sesuai dengan tabel:
    fmt.Println(isValidScore(0))   // true
    fmt.Println(isValidScore(100)) // true
    fmt.Println(isValidScore(-1))  // false[cite: 1]
    fmt.Println(isValidScore(101)) // false[cite: 1]
    fmt.Println(isValidScore(78))  // true[cite: 1]
    fmt.Println(isValidScore(55))  // true[cite: 1]
}

