func konversiGramKeKarat(gram float64) float64 {
    return gram * 5
}

func main() {
    inputs := []float64{50.0, 100.00}

    for _, gram := range inputs {
        karat := konversiGramKeKarat(gram)
        fmt.Printf("Input: %.1f  ->  Result: %.7f\n", gram, karat)
    }
}

