program tukar_tiga_variabel
kamus
    x, y, z, temp : integer  {atau real}
algoritma
    read(x, y, z)

    temp <- x   {simpan nilai awal x}
    x <- z      {x diisi nilai awal z}
    z <- y      {z diisi nilai awal y}
    y <- temp   {y diisi nilai awal x}

    write(x, y, z)
endprogram

