ALGORITHM CheckSquareRoot
    // Declare integer variables for a and b, and a boolean for the result
    DECLARE a, b: INTEGER
    DECLARE result: BOOLEAN

    // Read the two integers
    READ a
    READ b

    // Check if a multiplied by a equals b without using conditionals
    result = (a * a == b)

    // Print the resulting boolean value
    PRINT result
END ALGORITHM

package main

