)

func main() {
	var a, b int

	// Read input integers a and b
	fmt.Scan(&a, &b)

	// Evaluate if a is the square root of b
	result := (a * a == b)

	// Print the boolean result
	fmt.Println(result)
}

ALGORITHM IsEven
    // Declare an integer variable for the number and a boolean for the result
    DECLARE n: INTEGER
    DECLARE result: BOOLEAN

    // Read the input integer
    READ n

    // Check if the number is divisible by 2 without using conditionals
    result = (n % 2 == 0)

    // Print the resulting boolean value
    PRINT result
END ALGORITHM

