package main

import "fmt"

func main() {
	// Catatan 1: Deklarasikan pi sebagai konstanta dengan nilai 3.14
	const pi = 3.14

	var r float64

	// Melakukan perulangan untuk membaca semua test case hingga input habis
	for {
		_, err := fmt.Scan(&r)
		if err != nil {
			break // Berhenti jika semua input uji dari sistem sudah habis terbaca
		}

		// Catatan 2: Gunakan rumus 2 * pi * r untuk menghitung keliling
		keliling := 2 * pi * r

		// Mengeluarkan keluaran presisi tinggi (6 angka di belakang koma)
		fmt.Printf("%.6f\n", keliling)
	}
}

