package main

import "fmt"

func main() {
    // Catatan 1: Deklarasikan pi sebagai konstanta
    const pi = 3.14

    var r float64
    var volume float64

    // Membaca masukan berupa jari-jari bola
    fmt.Scan(&r)

    // Catatan 2: Gunakan rumus (4/3) * pi * r^3
    // Ditulis 4.0 / 3.0 agar terbaca sebagai bilangan desimal/riil
    volume = (4.0 / 3.0) * pi * r * r * r

    // Mencetak keluaran volume bola dengan format 7 angka desimal
    fmt.Printf("%.7f\n", volume)
}

