KAMUS
  konstanta pi = 3.14  { Catatan 1 }
  r    : real          { Masukan jari-jari lingkaran dalam bilangan riil }
  luas : real          { Keluaran luas lingkaran dalam bilangan riil }

ALGORITMA:
  baca(r)
  luas <- pi * r ^ 2   { Catatan 2: Menggunakan rumus pi * r^2 }
  tulis(luas)
EndProgram

ALGORITMA LuasLingkaran

KAMUS
    konstanta pi : real = 3.14
    r            : real    { jari-jari lingkaran }
    luas         : real    { luas lingkaran }

DESKRIPSI
    input(r)
    luas ← pi * r * r        { pi * r^2 }
    output(luas)

package main

import "fmt"

func main() {
    const pi = 3.14

    var volumeBola, volumeKotak float64

    fmt.Scan(&volumeBola, &volumeKotak)

    if 6*volumeBola <= pi*volumeKotak {
        fmt.Println(true)
    } else {
        fmt.Println(false)
    }
}

