package main

import "fmt"

func main() {
	// KAMUS
	const pi float64 = 3.14
	var volumeBola, volumeKotak float64
	var kondisi bool

	// ALGORITMA
	fmt.Scan(&volumeBola, &volumeKotak)

	kondisi = (6 * volumeBola) <= (pi * volumeKotak)

	fmt.Println(kondisi)
}

package main

import (
	"fmt"
)

func main() {
	// Deklarasi konstanta
	const pi float64 = 3.14

	// Deklarasi variabel
	var volumeBola, volumeKotak float64
	var hasil bool

	// Membaca masukan dari pengguna
	fmt.Print("Masukkan volume bola: ")
	fmt.Scan(&volumeBola)
	fmt.Print("Masukkan volume kotak: ")
	fmt.Scan(&volumeKotak)

	// Menghitung berdasarkan kondisi ekuivalen
	hasil = (6 * volumeBola) <= (pi * volumeKotak)

	// Menampilkan keluaran (true/false)
	fmt.Println("Apakah bola dapat masuk? ", hasil)
}

