package main

import (
	"fmt"
)

func main() {
	var inputVal bool

	// Membaca input boolean ("true" atau "false")
	fmt.Scanln(&inputVal)

	// Membalik nilai menggunakan operator logika NOT (!)
	outputVal := !inputVal

	// Menampilkan hasil balikannya
	fmt.Println(outputVal)
}

program CekDigitMenaik

kamus
    n : integer
    d1, d2, d3, d4 : integer
    hasil : boolean

algoritma
    // Menerima input satu bilangan bulat 4 digit
    input(n)

    // Memisahkan masing-masing digit
    // Contoh: jika n = 2345
    d4 <- n mod 10              // d4 = 5
    d3 <- (n div 10) mod 10     // d3 = 4
    d2 <- (n div 100) mod 10    // d2 = 3
    d1 <- n div 1000            // d1 = 2

    // Mengevaluasi apakah digit tersusun menaik (kiri ke kanan)
    // dan langsung menyimpan hasilnya (true/false)
    hasil <- (d1 < d2) and (d2 < d3) and (d3 < d4)

    // Mencetak hasil
    output(hasil)
endprogram

