program KonversiKoin

kamus
    drachma : integer
    attic_talent, mine, oboli : integer

algoritma
    // Menerima input jumlah koin drachma
    input(drachma)

    // 1 attic talent = 6000 drachma
    attic_talent <- drachma div 6000

    // Menghitung sisa drachma setelah diambil untuk talent,
    // lalu dibagi 100 untuk mendapatkan jumlah mine
    mine <- (drachma mod 6000) div 100

    // Sisa drachma yang tidak bisa menjadi talent maupun mine
    // dikalikan 6 untuk menjadi oboli
    oboli <- (drachma mod 100) * 6

    // Mencetak hasil keluaran secara berurutan
    output(attic_talent)
    output(mine)
    output(oboli)
endprogram

program CekTahunKabisat

kamus
    tahun : integer
    hasil : boolean

algoritma
    // Menerima input satu bilangan bulat positif (tahun)
    input(tahun)

    // Mengevaluasi kondisi tahun kabisat dan menyimpannya langsung
    // sebagai nilai boolean true atau false
    hasil <- (tahun mod 400 == 0) or ((tahun mod 4 == 0) and (tahun mod 100 != 0))

    // Mencetak hasil keluaran
    output(hasil)
endprogram

program CekVokal

kamus
    huruf : char
    hasil : boolean

algoritma
    // Menerima input satu karakter huruf kecil
    input(huruf)

    // Mengevaluasi apakah huruf adalah a, i, u, e, ATAU o
    // Kelompokkan menggunakan tanda kurung sesuai petunjuk soal
    hasil <- (huruf == 'a') or (huruf == 'i') or (huruf == 'u') or (huruf == 'e') or (huruf == 'o')

    // Mencetak hasil keluaran (true/false)
    output(hasil)
endprogram

program CekDaduBerurutan

kamus
    d1, d2, d3 : integer
    hasil : boolean

algoritma
    // Menerima input nilai dari ketiga dadu
    input(d1, d2, d3)

    // Mengevaluasi selisih d1 dan d2 adalah 1 atau -1
    // DAN selisih d2 dan d3 juga 1 atau -1
    hasil <- ((d1 - d2 == 1) or (d1 - d2 == -1)) and ((d2 - d3 == 1) or (d2 - d3 == -1))

    // Mencetak hasil (true/false)
    output(hasil)
endprogram

program CekDaduGanjil

kamus
    d1, d2, d3 : integer
    hasil : boolean

algoritma
    // Menerima input nilai dari ketiga dadu
    input(d1, d2, d3)

    // Mengevaluasi apakah d1, d2, dan d3 semuanya ganjil
    // (sisa bagi dengan 2 tidak sama dengan 0)
    hasil <- (d1 mod 2 != 0) and (d2 mod 2 != 0) and (d3 mod 2 != 0)

    // Mencetak hasil (true/false)
    output(hasil)
endprogram

program CekGameOver

kamus
    health, score, level : integer
    game_over : boolean

algoritma
    // Menerima input health, score, dan level
    input(health, score, level)

    // Syarat lanjut permainan adalah:
    // health > 0 DAN salah satu dari syarat skor terpenuhi
    // Karena output true = game over, maka kita beri operator NOT (kebalikan dari syarat lanjut)
    game_over <- not ((health > 0) and ((level == 1 and score >= 1000) or (level == 2 and score >= 3000) or (score >= 7000)))

    // Mencetak hasil (true untuk game over, false untuk bisa lanjut)
    output(game_over)
endprogram

program CekPemenang

kamus
    adik, kakak : integer
    hasil : boolean

algoritma
    // Menerima input angka dari adik dan kakak
    input(adik, kakak)

    // Adik menang jika:
    // 1. Angka sama (adik == kakak), ATAU
    // 2. Selisih absolut 1 (adik - kakak == 1 ATAU adik - kakak == -1), ATAU
    // 3. Selisih absolut 5 (adik - kakak == 5 ATAU adik - kakak == -5)
    hasil <- (adik == kakak) or (adik - kakak == 1) or (adik - kakak == -1) or (adik - kakak == 5) or (adik - kakak == -5)

    // Mencetak hasil keluaran (true/false)
    output(hasil)
endprogram

